const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg',COL=['#f6c343','#5dd6c5','#ff6b6b','#6ea8fe','#63d471','#b892ff','#ff9f43','#e879f9'];
function fmt(v){return v==null?'—':Number(v).toLocaleString('fr-FR',{maximumFractionDigits:1})}
function pct(a,b){return a&&b?((b/a-1)*100).toFixed(1).replace('.',',')+'%':'—'}
function el(n,a={}){const e=document.createElementNS(NS,n);for(const k in a)e.setAttribute(k,a[k]);return e}
function path(vals,x,y){return vals.map((v,i)=>v==null?'':`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ')}

function drawLineChart(svgId,legendId,labels,sets,active,onToggle){
  const svg=$(svgId),legend=$(legendId),W=1100,H=420,l=58,r=20,t=24,b=46;
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.textContent='';
  const visible=sets.filter(s=>active[s.key]);
  let vals=visible.flatMap(s=>s.values).filter(v=>v!=null);
  if(!vals.length)vals=[0,100];
  let min=Math.floor(Math.min(...vals)/10)*10,max=Math.ceil(Math.max(...vals)/10)*10;
  if(min===max){min-=10;max+=10}
  const x=i=>l+(W-l-r)*(i/(labels.length-1||1)),y=v=>H-b-(H-t-b)*(v-min)/(max-min||1);
  svg.append(el('rect',{width:W,height:H,fill:'transparent'}));
  for(let gy=min;gy<=max;gy+=Math.max(20,Math.ceil((max-min)/8/10)*10)){
    svg.append(el('line',{x1:l,y1:y(gy),x2:W-r,y2:y(gy),stroke:'rgba(255,255,255,.10)'}));
    let tx=el('text',{x:l-8,y:y(gy)+4,'text-anchor':'end','font-size':11,fill:'#aebbd4'});
    tx.textContent=gy;svg.append(tx)
  }
  labels.forEach((yr,i)=>{
    if(i%Math.ceil(labels.length/10)===0||i===labels.length-1){
      let tx=el('text',{x:x(i),y:H-18,'text-anchor':'middle','font-size':11,fill:'#aebbd4'});
      tx.textContent=yr;svg.append(tx)
    }
  });
  svg.append(el('line',{x1:l,y1:t,x2:l,y2:H-b,stroke:'rgba(255,255,255,.28)'}));
  svg.append(el('line',{x1:l,y1:H-b,x2:W-r,y2:H-b,stroke:'rgba(255,255,255,.28)'}));
  sets.forEach((s,si)=>{
    if(!active[s.key])return;
    svg.append(el('path',{d:path(s.values,x,y),fill:'none',stroke:COL[si%COL.length],'stroke-width':s.bold?4:2.5,'stroke-linecap':'round','stroke-linejoin':'round'}))
  });
  let hover=el('g');svg.append(hover);
  labels.forEach((yr,i)=>{
    const rw=(W-l-r)/(labels.length-1||1),rect=el('rect',{x:i===0?l:x(i)-rw/2,y:t,width:i===labels.length-1?rw/2+(W-r-x(i)):rw,height:H-t-b,fill:'transparent'});
    rect.addEventListener('mousemove',ev=>{
      hover.textContent='';
      hover.append(el('line',{x1:x(i),y1:t,x2:x(i),y2:H-b,stroke:'rgba(255,255,255,.45)','stroke-dasharray':'4 4'}));
      const rows=sets.filter(s=>active[s.key]).map((s,idx)=>`<div><span class="dot" style="background:${COL[sets.indexOf(s)%COL.length]}"></span>${s.label}: <b>${fmt(s.values[i])}</b></div>`).join('');
      const tt=$('tooltip');tt.style.display='block';tt.style.left=(ev.clientX+14)+'px';tt.style.top=(ev.clientY+14)+'px';tt.innerHTML=`<b>${yr}</b>${rows}`
    });
    svg.append(rect)
  });
  svg.addEventListener('mouseleave',()=>{$('tooltip').style.display='none';hover.textContent=''});
  legend.innerHTML=sets.map((s,i)=>`<button type="button" class="${active[s.key]?'':'off'}" data-key="${s.key}" aria-pressed="${active[s.key]}"><span class="dot" style="background:${COL[i%COL.length]}"></span>${s.label}</button>`).join('');
  legend.querySelectorAll('button').forEach(b=>b.onclick=()=>onToggle(b.dataset.key))
}

