function drawBudget(){
  const svg=$('budgetSvg'),W=700,H=420,cx=350,cy=205,r=125,data=[['Logement',28],['Alimentation',17],['Transport / énergie',14],['Impôts & prélèvements',18],['Santé',8],['Loisirs / reste à vivre',15]];
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.textContent='';
  let total=data.reduce((a,b)=>a+b[1],0),ang=-Math.PI/2;
  data.forEach((d,i)=>{
    let a2=ang+2*Math.PI*d[1]/total,x1=cx+r*Math.cos(ang),y1=cy+r*Math.sin(ang),x2=cx+r*Math.cos(a2),y2=cy+r*Math.sin(a2),large=a2-ang>Math.PI?1:0;
    svg.append(el('path',{d:`M${cx},${cy} L${x1},${y1} A${r},${r} 0 ${large},1 ${x2},${y2} Z`,fill:COL[i%COL.length],opacity:.9}));
    ang=a2
  });
  svg.append(el('circle',{cx,cy,r:70,fill:'#111936'}));
  let txt=el('text',{x:cx,y:cy-4,'text-anchor':'middle','font-size':18,fill:'#eef3ff','font-weight':800});txt.textContent='Budget';svg.append(txt);
  let sub=el('text',{x:cx,y:cy+20,'text-anchor':'middle','font-size':12,fill:'#aebbd4'});sub.textContent='type';svg.append(sub);
  $('budgetLegend').innerHTML=data.map((d,i)=>`<button type="button"><span class="dot" style="background:${COL[i%COL.length]}"></span>${d[0]} — ${d[1]}%</button>`).join('')
}

