function yearsRange(){let sy=+$('simStartYear').value,ey=+$('simEndYear').value;if(ey<sy)[sy,ey]=[ey,sy];$('simStartYear').value=sy;$('simEndYear').value=ey;return Array.from({length:ey-sy+1},(_,i)=>sy+i)}
function series(k,ys){let vals=ys.map(y=>simData[k]?.[y]??null);for(let i=0;i<vals.length;i++)if(vals[i]==null){let a=i-1;while(a>=0&&vals[a]==null)a--;let b=i+1;while(b<vals.length&&vals[b]==null)b++;if(a>=0&&b<vals.length)vals[i]=vals[a]+(vals[b]-vals[a])*(i-a)/(b-a)}let base=vals.find(v=>v!=null);return vals.map(v=>v==null||!base?null:v/base*100)}
function drawSimulator(){const ys=yearsRange(),idx=Object.fromEntries(['official','food','energy','housing','wageMean','wageMedian'].map(k=>[k,series(k,ys)])),wage=idx[$('simWageMode').value==='median'?'wageMedian':'wageMean'],w={food:+$('simWFood').value||0,energy:+$('simWEnergy').value||0,housing:+$('simWHousing').value||0,official:+$('simWOfficial').value||0},sum=Object.values(w).reduce((a,b)=>a+b,0)||1,real=ys.map((_,i)=>((idx.food[i]??idx.official[i])*w.food+(idx.energy[i]??idx.official[i])*w.energy+(idx.housing[i]??idx.official[i])*w.housing+(idx.official[i]??100)*w.official)/sum),paOff=ys.map((_,i)=>wage[i]&&idx.official[i]?wage[i]/idx.official[i]*100:null),paReal=ys.map((_,i)=>wage[i]&&real[i]?wage[i]/real[i]*100:null),all={...idx,paOff,paReal};const sets=Object.entries(simLabels).map(([key,label])=>({key,label,values:all[key],bold:key.startsWith('pa')}));drawLineChart('simSvg','simSeriesControls',ys,sets,simActive,k=>{simActive[k]=!simActive[k];drawSimulator()});const first=ys.findIndex((_,i)=>paOff[i]&&paReal[i]),last=ys.length-1;$('simPaOfficial').textContent=first>=0?pct(paOff[first],paOff[last]):'—';$('simPaReal').textContent=first>=0?pct(paReal[first],paReal[last]):'—';$('simGap').textContent=first>=0&&paReal[last]&&paOff[last]?(paReal[last]-paOff[last]).toFixed(1).replace('.',',')+' pts':'—';$('simPeriod').textContent=ys[0]+'–'+ys[last];$('simStatus').textContent='Calcul OK. Les séries visibles sont normalisées base 100 sur l\'année de départ.';renderSources()}
function parseCSV(txt){const out={};txt.split(/\r?\n/).forEach(line=>{const [a,b]=line.split(/[;,\t]/),y=String(a||'').match(/(18|19|20)\d{2}/),v=String(b||'').replace(/\s/g,'').replace(',','.');if(y&&!Number.isNaN(parseFloat(v)))out[+y[0]]=parseFloat(v)});return out}
function importSimulatorCSV(){const f=$('simCsvFile').files[0],k=$('simImportKey').value;if(!f){alert('Sélectionner un CSV year,value.');return}const r=new FileReader();r.onload=()=>{const p=parseCSV(r.result);if(Object.keys(p).length<2){alert('CSV non reconnu. Format attendu : year,value');return}simData[k]=p;drawSimulator()};r.readAsText(f)}
function downloadSimulatorTemplate(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['year,value\n1996,100\n1997,101.2\n'],{type:'text/csv'}));a.download='modele_serie_lefrancaismoyen.csv';a.click()}
