function demoInterp(a,y){if(y<=a[0][0])return a[0][1];if(y>=a.at(-1)[0])return a.at(-1)[1];for(let i=1;i<a.length;i++)if(y<=a[i][0]){const[y0,v0]=a[i-1],[y1,v1]=a[i];return v0+(v1-v0)*(y-y0)/(y1-y0)}}
function demoMortality(age){if(age<5)return .0025;if(age<20)return .00025;if(age<35)return .00055;if(age<50)return .0014;if(age<65)return .0045;if(age<75)return .014;if(age<85)return .040;if(age<90)return .085;if(age<95)return .180;return .380}
function demoFertilityWeight(age){return age<15||age>49?0:Math.exp(-Math.pow((age-30)/8.5,2))}
function demoNormalize(arr,t){const s=arr.reduce((a,b)=>a+b,0)||1;return arr.map(v=>v/s*t)}
function demoInitialAgeVector(total,p,cat){const center=cat==='long'?52:cat==='foreign'?34:26,spread=cat==='long'?26:cat==='foreign'?20:18;return demoNormalize(demoAgeBands.map(a=>{const base=Math.exp(-Math.pow((a-center)/spread,2)),young=(cat==='mixed'?.9:cat==='foreign'?.4:.15)*Math.exp(-Math.pow((a-12)/14,2)),old=a>80?Math.exp(-(a-80)/8):1;return Math.max(.00001,(base+young)*old)}),total)}
function demoClamp(s){const caps={long:.004,foreign:.0025,mixed:.002};for(const c of ['long','foreign','mixed']){const total=s[c].reduce((a,b)=>a+b,0),cap=total*caps[c];if(s[c][19]>cap){const ex=s[c][19]-cap;s[c][19]=cap;[15,16,17,18].forEach((b,i)=>s[c][b]+=ex*[.15,.25,.30,.30][i])}}return s}
function demoTotals(s){return{long:s.long.reduce((a,b)=>a+b,0),foreign:s.foreign.reduce((a,b)=>a+b,0),mixed:s.mixed.reduce((a,b)=>a+b,0)}}
function demoFrance(end){let years=[],total=[],long=[],foreign=[],mixed=[],L,F,M,T;for(let y=1900;y<=end;y++){if(y<=2024){T=demoInterp(demoTotalAnchors,y);const imm=demoInterp(demoImmAnchors,y),desc=y<1950?0:8*Math.pow((y-1950)/(2024-1950),1.55);M=Math.max(0,Math.min(T*.32,desc*(.18+.37*Math.pow(Math.max(0,y-1960)/(2024-1960),1.1))));F=Math.max(0,Math.min(T-M,imm+desc-M));L=Math.max(0,T-F-M)}else{T=total.at(-1)+total.at(-1)*(-.0006)+(+$('demoMigration').value/1e6);F=foreign.at(-1);M=mixed.at(-1);L=long.at(-1)}years.push(y);total.push(T);long.push(L);foreign.push(F);mixed.push(M)}return{years,total,long,foreign,mixed}}
function demoRegionalize(fr,name){const p=demoProfiles[name];if(name==='France entière')return fr;const out={years:fr.years,total:[],long:[],foreign:[],mixed:[]};fr.years.forEach((y,i)=>{const time=y<=2024?(y-1900)/124:1,share=p.share*Math.pow(p.growth,Math.max(0,y-2024)/55),T=fr.total[i]*share;let f=(fr.foreign[i]/fr.total[i])*p.foreign*(.82+.18*time),m=(fr.mixed[i]/fr.total[i])*p.mix*(.86+.14*time);f=Math.min(.58,Math.max(.01,f));m=Math.min(.42,Math.max(0,m));if(f+m>.76){const k=.76/(f+m);f*=k;m*=k}out.total.push(T);out.foreign.push(T*f);out.mixed.push(T*m);out.long.push(T*(1-f-m))});return out}
function demoStepAges(state,params,p){const cats=['long','foreign','mixed'],next={long:Array(20).fill(0),foreign:Array(20).fill(0),mixed:Array(20).fill(0)};for(const c of cats)for(let i=19;i>=0;i--){const surv=state[c][i]*(1-demoMortality(demoAgeBands[i]+2.5)),move=surv*.20;next[c][i]+=surv-move;if(i<19)next[c][i+1]+=move;else next[c][i]+=move}const ft={long:state.long.reduce((s,v,i)=>s+v*demoFertilityWeight(demoAgeBands[i]+2.5),0)*params.fertLong,foreign:state.foreign.reduce((s,v,i)=>s+v*demoFertilityWeight(demoAgeBands[i]+2.5),0)*params.fertForeign,mixed:state.mixed.reduce((s,v,i)=>s+v*demoFertilityWeight(demoAgeBands[i]+2.5),0)*1.03},den=ft.long+ft.foreign+ft.mixed||1,t0=demoTotals(state),T=t0.long+t0.foreign+t0.mixed,births=T*.0102;let bL=births*ft.long/den,bF=births*ft.foreign/den,bM=births*ft.mixed/den;const sL=t0.long/T,sF=t0.foreign/T,sM=t0.mixed/T,mixedBirths=params.mixing*births*(2*sL*sF+sL*sM+sF*sM);bL=Math.max(0,bL-mixedBirths*.55);bF=Math.max(0,bF-mixedBirths*.45);bM+=mixedBirths;next.long[0]+=bL;next.foreign[0]+=bF;next.mixed[0]+=bM;const fs=next.foreign.reduce((a,b)=>a+b,0)||1,shift=params.assim*t0.foreign;for(let i=0;i<20;i++){const part=next.foreign[i]/fs*shift;next.foreign[i]-=part;next.mixed[i]+=part}const mig=params.migration*p.mig;next.foreign[4]+=mig*.28;next.foreign[5]+=mig*.34;next.foreign[6]+=mig*.22;next.foreign[7]+=mig*.10;next.foreign[8]+=mig*.06;const raw=demoTotals(next),scale=Math.max(0,T+births-T*.0108+mig)/((raw.long+raw.foreign+raw.mixed)||1);for(const c of cats)for(let i=0;i<20;i++)next[c][i]*=scale;const after=demoTotals(next),afterT=after.long+after.foreign+after.mixed,intensity=(params.internalMob||0)*(p.internal||0.18)/Math.max(afterT,1),target={long:.58,foreign:.22,mixed:.20};if(intensity>0){const cur={long:after.long/afterT,foreign:after.foreign/afterT,mixed:after.mixed/afterT},desired={long:afterT*(cur.long+(target.long-cur.long)*intensity),foreign:afterT*(cur.foreign+(target.foreign-cur.foreign)*intensity),mixed:afterT*(cur.mixed+(target.mixed-cur.mixed)*intensity)};for(const c of cats)next[c]=demoNormalize(next[c],desired[c])}return demoClamp(next)}
function demoRegionalCohorts(name,end){const p=demoProfiles[name],historical=demoRegionalize(demoFrance(Math.min(end,2024)),name),years=[],total=[],long=[],foreign=[],mixed=[],byYear={};historical.years.forEach((y,i)=>{if(y<1950){years.push(y);total.push(historical.total[i]);long.push(historical.long[i]);foreign.push(historical.foreign[i]);mixed.push(historical.mixed[i])}});const b1950=demoRegionalize(demoFrance(1950),name),i1950=b1950.years.indexOf(1950);let state={long:demoInitialAgeVector(b1950.long[i1950],p,'long'),foreign:demoInitialAgeVector(b1950.foreign[i1950],p,'foreign'),mixed:demoInitialAgeVector(b1950.mixed[i1950],p,'mixed')},params={migration:+$('demoMigration').value/1e6,internalMob:+$('demoInternalMob').value/1e6,fertLong:+$('demoFertLong').value,fertForeign:+$('demoFertForeign').value,mixing:+$('demoMixing').value,assim:+$('demoAssim').value};for(let y=1950;y<=end;y++){if(y>1950)state=demoStepAges(state,params,p);if(y<=2024){const h=demoRegionalize(demoFrance(y),name),ih=h.years.indexOf(y),tar={long:h.long[ih],foreign:h.foreign[ih],mixed:h.mixed[ih]};for(const c of ['long','foreign','mixed'])state[c]=demoNormalize(state[c],tar[c]);state=demoClamp(state)}byYear[y]=JSON.parse(JSON.stringify(state));const t=demoTotals(state),T=t.long+t.foreign+t.mixed;years.push(y);total.push(T);long.push(t.long);foreign.push(t.foreign);mixed.push(t.mixed)}return{years,total,long,foreign,mixed,byYear}}
