// ── Calculateur d'impact personnel ───────────────────────────────────────────
function calcPersonalImpact() {
  try {
    const inputEl = document.getElementById('birthYear');
    const resultEl = document.getElementById('personalResult');
    if (!inputEl || !resultEl) return;

    const year = parseInt(inputEl.value) || 1985;
    const now = 2024;
    const workStart = Math.min(now - 1, Math.max(2000, year + 22));
    const yearsWork = now - workStart;

    const foodRate    = 0.0143;
    const housingRate = 0.0422;
    const salaryRate  = 0.0018;

    const foodUp    = Math.round((Math.pow(1 + foodRate,    yearsWork) - 1) * 100);
    const houseUp   = Math.round((Math.pow(1 + housingRate, yearsWork) - 1) * 100);
    const salaryUp  = Math.round((Math.pow(1 + salaryRate,  yearsWork) - 1) * 100);
    const basketNow = Math.round(100 * Math.pow(1 + foodRate, yearsWork));
    const houseNow  = Math.round(150 * Math.pow(1 + housingRate, yearsWork));

    const set = (id, txt) => { const e = document.getElementById(id); if (e) e.textContent = txt; };
    set('pr1', 'Courses : +' + foodUp + '% depuis ' + workStart);
    set('pr2', 'Un panier de 100 € en coûte ' + basketNow + ' aujourd\'hui.');
    set('pr3', 'Logement : +' + houseUp + '% sur la même période');
    set('pr4', 'Un bien à 150 000 € vaut maintenant ~' + houseNow + ' 000 €.');
    set('pr5', 'Salaire réel : +' + salaryUp + '% seulement');
    set('pr6', 'Les prix ont progressé ' + Math.round(foodUp / Math.max(1, salaryUp)) + '× plus vite que les salaires.');

    resultEl.style.display = 'grid';
    resultEl.style.gap = '8px';

    const shareBtn = document.getElementById('sharePersonal');
    if (shareBtn) {
      const text = 'Depuis ' + workStart + ', mon panier de courses a augmenté de ' + foodUp + '%, le logement de ' + houseUp + '%… mais les salaires réels de ' + salaryUp + '% seulement. Les chiffres officiels : le-francais-moyen.com';
      shareBtn.onclick = function() {
        if (navigator.share) {
          navigator.share({ title: 'Mon bilan — Le Français Moyen', text: text, url: 'https://le-francais-moyen.com/' });
        } else if (navigator.clipboard) {
          navigator.clipboard.writeText(text).then(function() { shareBtn.textContent = '✓ Copié !'; setTimeout(function() { shareBtn.textContent = 'Partager mon bilan'; }, 2500); });
        }
      };
    }
  } catch(e) { console.error('calcPersonalImpact:', e); }
}

(function() {
  var btn = document.getElementById('calcPersonalBtn');
  var inp = document.getElementById('birthYear');
  if (btn) btn.addEventListener('click', calcPersonalImpact);
  if (inp) inp.addEventListener('keydown', function(e) { if (e.key === 'Enter') calcPersonalImpact(); });
})();

// ── Animations de compteur (scroll-triggered) ─────────────────────────────────
function animateCounter(el, target, suffix, duration) {
  const start = performance.now();
  const isFloat = String(target).includes('.');
  const from = 0;
  function step(now) {
    const progress = Math.min((now - start) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic
    const current = from + (target - from) * eased;
    el.textContent = (isFloat ? current.toFixed(1) : Math.round(current)).toLocaleString('fr-FR') + suffix;
    if (progress < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

function initCounters() {
  const kpis = [
    { id: 'kpiPurchasing', target: 0.8,  suffix: '%',  duration: 1200 },
    { id: 'kpiFood',       target: 7.2,  suffix: '%',  duration: 1400 },
    { id: 'kpiDebt',       target: 110,  suffix: '%',  duration: 1600 },
  ];
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      const kpi = kpis.find(k => k.id === entry.target.id);
      if (kpi) {
        animateCounter(entry.target, kpi.target, kpi.suffix, kpi.duration);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });

  kpis.forEach(k => { const el = $(k.id); if (el) observer.observe(el); });
}
initCounters();

// ── Newsletter (stockage local + feedback) ────────────────────────────────────
function handleNewsletter(e) {
  e.preventDefault();
  const email = $('newsletterEmail').value.trim();
  const msg   = $('newsletterMsg');
  if (!email) return;

  // Store locally so user sees confirmation even without backend
  try {
    const subs = JSON.parse(localStorage.getItem('lfm_subs') || '[]');
    if (!subs.includes(email)) subs.push(email);
    localStorage.setItem('lfm_subs', JSON.stringify(subs));
  } catch (_) {}

  msg.style.display = 'block';
  msg.textContent   = '✓ Inscription enregistrée — vous recevrez le prochain chiffre de la semaine.';
  $('newsletterEmail').value = '';

  // If a Brevo / Mailchimp endpoint is configured via a Netlify function, call it
  fetch('/api/subscribe', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email }),
  }).catch(() => {}); // silent fail — backend optional
}

// ── Toggle "Voir plus" pour les panneaux de détails ───────────────────────
(function initVoirPlus() {
  document.querySelectorAll('.btn-voir-plus').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var body = btn.closest('aside, .panel').querySelector('.voir-plus-body');
      if (!body) return;
      var open = !body.hidden;
      body.hidden = open;
      btn.textContent = open ? 'Voir plus ▾' : 'Voir moins ▴';
      btn.setAttribute('aria-expanded', String(!open));
    });
  });
})();

